function setupShop(){let root=$('#shopItems');root.innerHTML=shopCatalog.map(([name,desc,price],i)=>`<button class="item" data-index="${i}"><div class="item-name">${name}</div><div class="item-desc">${desc}</div><div class="price">$${price}</div></button>`).join('');root.querySelectorAll('.item').forEach(el=>el.onclick=()=>buyItem(Number(el.dataset.index)))}
