function toast(text){$('#toast').textContent=text;$('#toast').style.opacity=1;toastTimer=3}
function showPause(){if(!playing||roundEnded)return;paused=true;$('#pause').classList.add('open');if(document.pointerLockElement)document.exitPointerLock()}
function hidePause(){paused=false;$('#pause').classList.remove('open');if(playing&&innerWidth>700)renderer.domElement.requestPointerLock?.()}
function onKeyDown(e){keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.repeat)return;if(e.code==='Escape'){if($('#shop').classList.contains('open'))closeShop();else if(paused)hidePause();else if(playing)showPause()}if(e.code==='KeyB'&&phase==='buy')$('#shop').classList.contains('open')?closeShop():openShop();if(e.code==='ControlLeft'||e.code==='ControlRight')isCrouched=!isCrouched;if(e.code==='ShiftLeft'||e.code==='ShiftRight')isSlow=!isSlow;if(e.code==='KeyF')useAction();if(e.code==='KeyQ')throwGrenade('smoke');if(e.code==='KeyG')throwGrenade('flash');if(e.code==='KeyR')reload();if(e.code==='KeyV')aiming=!aiming}
