function beginLive(){if(phase!=='buy')return;phase='live';roundLeft=120;$('#phaseLabel').textContent='RODADA EM ANDAMENTO';closeShop();toast('Rodada iniciada!');if(team==='T'&&bombHolder==='player')toast('Você está com a bomba: plante em A ou B.');}
function movePlayer(dt){if(!playerAlive||phase==='buy')return;let forward=(keys.KeyW||keys.ArrowUp?1:0)-(keys.KeyS||keys.ArrowDown?1:0)-moveVector.y,right=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0)+moveVector.x;let v=new THREE.Vector3(Math.sin(yaw)*forward+Math.cos(yaw)*right,0,-Math.cos(yaw)*forward+Math.sin(yaw)*right);if(v.lengthSq()>1)v.normalize();let speed=isCrouched?2.1:isSlow?2.7:6.4;if(aiming)speed*=.7;v.multiplyScalar(speed*dt);let next=playerPos.clone().add(v);if(!collides(next,.42))playerPos.copy(next);playerPos.x=clamp(playerPos.x,-32.5,32.5);playerPos.z=clamp(playerPos.z,-26.5,26.5);moveAccum+=v.length();let bob=Math.sin(moveAccum*2.7)*Math.min(.035,v.length()*2);camera.position.set(playerPos.x,isCrouched?1.05:1.68,playerPos.z);camera.rotation.set(pitch,yaw,0,'YXZ');camera.position.y+=bob;if(camera.userData.weapon){camera.userData.weapon.position.y=-.28+(v.length()?Math.sin(moveAccum*5)*.018:0)}updateBombVisual()}
function collides(p,r){for(const o of obstacles){if(o.y-o.h/2>1.8||o.y+o.h/2<0)continue;let x=clamp(p.x,o.x-o.w/2,o.x+o.w/2),z=clamp(p.z,o.z-o.d/2,o.z+o.d/2);if((p.x-x)**2+(p.z-z)**2<r*r)return true}return false}
function targetFor(bot){let d=bot.userData,candidates=bots.filter(x=>x.userData.alive&&x.userData.side!==d.side);if(team!==d.side&&playerAlive)candidates.push({position:playerPos,userData:{side:team,isPlayer:true,alive:true}});if(d.side==='T'&&d.hasBomb&&bombState==='carried'){let site=sites.A.distanceTo(bot.position)<sites.B.distanceTo(bot.position)?sites.A:sites.B;return {position:site,userData:{site:true}}}if(bombState==='planted'&&d.side==='CT')return {position:bombObject.position,userData:{bomb:true}};if(!candidates.length)return null;candidates.sort((a,b)=>a.position.distanceToSquared(bot.position)-b.position.distanceToSquared(bot.position));return candidates[0]}
function botMove(bot,target,dt){let d=bot.userData;if(!target)return;let dest=target.position.clone();if(target.userData.site&&dest.distanceTo(bot.position)<4){if(!d.planting)d.planting=3.2;d.planting-=dt;if(d.planting<=0){bombState='planted';plantSite=dest===sites.A?'A':'B';bombTimer=40;bombHolder=null;d.hasBomb=false;bombObject.position.set(dest.x,.35,dest.z);toast('Bomba plantada no site '+plantSite+'!');feed(d.name,'BOMBA');d.planting=null}return}let dist=bot.position.distanceTo(dest),isEngaged=!target.userData.site&&dist<31;if(isEngaged){let dir=dest.clone().sub(bot.position);bot.rotation.y=Math.atan2(-dir.x,-dir.z);d.shoot-=dt;if(d.shoot<=0&&dist<26){d.shoot=rand(.65,1.5);if(Math.random()<clamp(.72-dist*.015,.16,.65)){if(target.userData.isPlayer)damagePlayer(rand(8,19));else if(target.userData.alive){target.userData.health-=rand(13,25);if(target.userData.health<=0)killBot(target,bot)}}}return}if(dist>.9){let dir=dest.clone().sub(bot.position);dir.y=0;dir.normalize();bot.rotation.y=Math.atan2(-dir.x,-dir.z);let step=dir.multiplyScalar(d.speed*dt);let next=bot.position.clone().add(step);if(!collides(next,.45))bot.position.copy(next);else{let side=new THREE.Vector3(-step.z,0,step.x);next=bot.position.clone().add(side);if(!collides(next,.45))bot.position.copy(next)}}}
function killBot(target,killer){let u=target.userData;if(!u.alive)return;u.alive=false;target.visible=false;if(u.hasBomb){bombState='dropped';bombHolder=null;bombObject.position.copy(target.position);bombObject.position.y=.35;u.hasBomb=false}feed(killer=== 'player'?'VOCÊ':killer.userData.name,u.name);if(u.side!==team)money+=300;checkElimination()}
function updateBots(dt){for(const b of bots){let d=b.userData;if(!d.alive)continue;d.think-=dt;if(d.think<=0){d.think=rand(.12,.3);d.target=targetFor(b)}if(d.target)botMove(b,d.target,dt);if(d.hasBomb&&bombState==='carried'&&d.position){let nearest=Object.entries(sites).sort((a,c)=>a[1].distanceToSquared(b.position)-c[1].distanceToSquared(b.position))[0];if(nearest&&nearest[1].distanceTo(b.position)<4&&!d.planting)d.planting=3.2}}}
function damagePlayer(d){if(!playerAlive)return;let absorbed=Math.min(playerArmor,d*.55);playerArmor-=absorbed;playerHealth-=d-absorbed;$('#damage').style.opacity='.6';setTimeout(()=>$('#damage').style.opacity='0',140);refreshHud();if(playerHealth<=0){playerHealth=0;playerAlive=false;$('#health').textContent='0';if(bombHolder==='player'){bombState='dropped';bombHolder=null;bombObject.position.copy(playerPos);bombObject.position.y=.35}feed('INIMIGO','VOCÊ');toast('Você foi eliminado. Acompanhe sua equipe.');checkElimination()}}
function checkElimination(){if(roundEnded)return;let enemy=bots.filter(b=>b.userData.alive&&b.userData.side!==team).length,own=bots.filter(b=>b.userData.alive&&b.userData.side===team).length;if(enemy===0&&(!playerAlive||true)){endRound(team==='T'?'T':'CT','Equipe inimiga eliminada.');return}if(own===0&&!playerAlive&&bombState!=='planted'){endRound(team==='T'?'CT':'T','Sua equipe foi eliminada.')}}
function endRound(winner,reason){if(roundEnded)return;roundEnded=true;phase='end';if(winner==='T')scoreT++;else scoreCT++;if(winner===team)money+=3250;refreshHud();$('#phaseLabel').textContent='RODADA ENCERRADA';$('#endTitle').textContent=winner===team?'VITÓRIA':'DERROTA';$('#endTitle').style.color=winner===team?'var(--lime)':'var(--red)';$('#endDesc').textContent=reason;$('#endcard').classList.add('open');if(document.pointerLockElement)document.exitPointerLock()}
function explodeBomb(){let p=bombObject.position;for(let b of bots)if(b.userData.alive&&b.position.distanceTo(p)<12)killBot(b,'BOMBA');if(playerAlive&&playerPos.distanceTo(p)<12)damagePlayer(120);endRound('T','A bomba explodiu!');}
function updateProgress(dt){if(progressAction){let valid=progressAction==='plant'?team==='T'&&bombState==='carried'&&bombHolder==='player'&&isCrouched&&sites[plantSite].distanceTo(playerPos)<4.4:team==='CT'&&bombState==='planted'&&bombObject.position.distanceTo(playerPos)<3.5;if(valid){progress+=dt/(progressAction==='plant'?3.2:(hasKit?4:8));$('#progress').style.display='block';$('#progressBar').style.width=Math.min(100,progress*100)+'%';if(progress>=1){if(progressAction==='plant'){bombState='planted';bombTimer=40;bombHolder=null;bombObject.position.set(sites[plantSite].x,.35,sites[plantSite].z);toast('BOMBA ARMADA — 40 SEGUNDOS!');$('#objective').querySelector('span').textContent='Bomba armada · '+plantSite+' · 00:40';feed('VOCÊ','BOMBA')}else endRound('CT','Bomba desarmada pela equipe CT.');progressAction='';progress=0;$('#progress').style.display='none'}}else{progressAction='';progress=0;$('#progress').style.display='none';toast('Ação cancelada.')}}else $('#progress').style.display='none'}
function updateProjectiles(dt){for(let i=projectiles.length-1;i>=0;i--){let p=projectiles[i];p.velocity.y-=9.8*dt;p.mesh.position.addScaledVector(p.velocity,dt);if(p.mesh.position.y<.2){p.mesh.position.y=.2;p.velocity.y*=-.35;p.velocity.x*=.72;p.velocity.z*=.72}p.time-=dt;if(p.time<=0){if(p.type==='smoke'){let cloud=new THREE.Mesh(new THREE.SphereGeometry(3.8,12,8),new THREE.MeshBasicMaterial({color:0x9ca5a0,transparent:true,opacity:.34,depthWrite:false}));cloud.position.copy(p.mesh.position);scene.add(cloud);smokeClouds.push({mesh:cloud,time:12})}else{let distance=camera.position.distanceTo(p.mesh.position);if(distance<18){flashTimer=2;$('#flash').style.transition='none';$('#flash').style.opacity=clamp(1-distance/18,.25,1);setTimeout(()=>{$('#flash').style.transition='opacity 1.5s';$('#flash').style.opacity=0},500)}for(let b of bots)if(b.userData.alive&&b.position.distanceTo(p.mesh.position)<10)b.userData.alert=2}scene.remove(p.mesh);projectiles.splice(i,1)}}for(let i=smokeClouds.length-1;i>=0;i--){let c=smokeClouds[i];c.time-=dt;c.mesh.material.opacity=Math.min(.36,c.time*.08);if(c.time<=0){scene.remove(c.mesh);c.mesh.geometry.dispose();c.mesh.material.dispose();smokeClouds.splice(i,1)}}}
function drawMinimap(){let c=$('#minimap'),ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height);ctx.fillStyle='#192220';ctx.fillRect(0,0,c.width,c.height);ctx.strokeStyle='#59645d';ctx.lineWidth=7;ctx.strokeRect(12,12,c.width-24,c.height-24);ctx.fillStyle='#6c6552';ctx.fillRect(93,56,94,76);ctx.fillStyle='#c9ef49';for(let [n,p]of Object.entries(sites)){ctx.beginPath();ctx.arc((p.x+35)/70*c.width,(p.z+28)/56*c.height,13,0,Math.PI*2);ctx.strokeStyle='#c9ef49';ctx.lineWidth=2;ctx.stroke();ctx.fillText(n,(p.x+35)/70*c.width-3,(p.z+28)/56*c.height+4)}for(let b of bots)if(b.userData.alive){ctx.fillStyle=b.userData.side===team?'#58baff':'#f35b52';ctx.fillRect((b.position.x+35)/70*c.width-2,(b.position.z+28)/56*c.height-2,4,4)}ctx.fillStyle='#d5fc3f';ctx.beginPath();ctx.arc((playerPos.x+35)/70*c.width,(playerPos.z+28)/56*c.height,4,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#d5fc3f';ctx.beginPath();ctx.moveTo((playerPos.x+35)/70*c.width,(playerPos.z+28)/56*c.height);ctx.lineTo((playerPos.x+35)/70*c.width+Math.sin(yaw)*10,(playerPos.z+28)/56*c.height-Math.cos(yaw)*10);ctx.stroke()}
function updateHud(){if(phase==='buy'){let s=Math.max(0,Math.ceil(buyLeft));$('#clock').textContent='00:'+String(s).padStart(2,'0');$('#shopClock').textContent=s}else if(phase==='live'){let t=bombState==='planted'?bombTimer:roundLeft;$('#clock').textContent=`${String(Math.floor(Math.max(0,t)/60)).padStart(2,'0')}:${String(Math.floor(Math.max(0,t)%60)).padStart(2,'0')}`;if(bombState==='planted')$('#objective').querySelector('span').textContent=`Bomba armada · ${plantSite} · ${$('#clock').textContent}`}}
function updateGame(dt){if(!playing||paused||roundEnded)return;if(phase==='buy'){buyLeft-=dt;if(buyLeft<=0)beginLive()}if(phase==='live'){if(roundLeft>0)roundLeft-=dt;if(bombState==='planted'){bombTimer-=dt;if(bombTimer<=0){explodeBomb();return}}else if(roundLeft<=0){endRound(bombState==='planted'?'T':'CT',bombState==='planted'?'A bomba permanece armada.':'Tempo esgotado: CT venceu.');return}if(shotCooldown>0)shotCooldown-=dt;if(fireHeld||keys.Mouse0)shoot();movePlayer(dt);updateBots(dt);updateProgress(dt);updateProjectiles(dt);if(flashTimer>0)flashTimer-=dt;updateHud();drawMinimap()}}
function animate(){requestAnimationFrame(animate);let dt=Math.min(clock3.getDelta(),.05);updateGame(dt);if(phase==='buy'&&playing&&!paused){movePlayer(dt);updateBots(dt);updateBombVisual();updateHud();drawMinimap()}renderer.render(scene,camera)}
renderer?.domElement?.addEventListener('mousedown',e=>{if(e.button===0){fireHeld=true;if(mouseLocked)shoot()}if(e.button===2)aiming=true});document.addEventListener('mouseup',e=>{if(e.button===0)fireHeld=false;if(e.button===2)aiming=false});document.addEventListener('contextmenu',e=>e.preventDefault());
init();
